import type { McpServer } from 'npm:@modelcontextprotocol/server@2.0.0'

import { registerTaskTools } from './tasks.ts'
import type { ToolContext } from './types.ts'
import { registerWhoamiTool } from './whoami.ts'

export type { ToolContext } from './types.ts'

// Add your product's tool modules here. The shared MCP runtime supplies the
// authenticated context for each request.
export function registerTools(server: McpServer, context: ToolContext): void {
  registerWhoamiTool(server, context)
  registerTaskTools(server, context)
}

import type { McpServer } from 'npm:@modelcontextprotocol/server@2.0.0'
import { z } from 'npm:zod@4.4.3'

import { errorResult, jsonResult, runtimeErrorResult } from './result.ts'
import type { ToolContext } from './types.ts'

const taskFields = 'id, title, closed, created_at'
const taskId = z.uuid().describe('The task ID returned by list_tasks or create_task.')
const taskTitle = z
  .string()
  .trim()
  .min(1)
  .max(200)
  .describe('A task title, 1–200 characters after trimming surrounding whitespace.')
const taskNotFound = 'Task not found or you do not have access.'

// Use only the caller's client. Ownership comes from auth.uid() in the schema,
// and RLS applies to reads and writes, including queries by a supplied task ID.
export function registerTaskTools(server: McpServer, { supabase }: ToolContext): void {
  server.registerTool(
    'list_tasks',
    {
      description:
        'List your tasks, newest first. Optionally filter by closed status. Pass next_offset as offset to fetch another page; null means there are no more tasks.',
      inputSchema: z.strictObject({
        closed: z.boolean().optional().describe('False for open tasks, true for closed tasks.'),
        limit: z.int().min(1).max(100).default(20).describe('Maximum tasks per page (1–100).'),
        offset: z.int().min(0).default(0).describe('Number of tasks to skip.'),
      }),
      annotations: {
        readOnlyHint: true,
        destructiveHint: false,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async ({ closed, limit, offset }) => {
      try {
        let query = supabase
          .from('tasks')
          .select(taskFields)
          .order('created_at', { ascending: false })
          .order('id', { ascending: false })
          .range(offset, offset + limit)

        if (closed !== undefined) query = query.eq('closed', closed)

        const { data } = await query.throwOnError()
        return jsonResult({
          tasks: data.slice(0, limit),
          next_offset: data.length > limit ? offset + limit : null,
        })
      } catch (error) {
        return runtimeErrorResult(error)
      }
    }
  )

  server.registerTool(
    'create_task',
    {
      description:
        'Create an open task for yourself and return it. Each call creates a new task; do not retry blindly after a connection failure.',
      inputSchema: z.strictObject({ title: taskTitle }),
      annotations: {
        readOnlyHint: false,
        destructiveHint: false,
        idempotentHint: false,
        openWorldHint: false,
      },
    },
    async ({ title }) => {
      try {
        const { data } = await supabase
          .from('tasks')
          .insert({ title })
          .select(taskFields)
          .single()
          .throwOnError()

        return jsonResult({ task: data })
      } catch (error) {
        return runtimeErrorResult(error)
      }
    }
  )

  server.registerTool(
    'update_task',
    {
      description:
        'Rename, close, or reopen one of your tasks and return it. Supply title, closed, or both. Fields you omit keep their current values.',
      inputSchema: z
        .strictObject({
          id: taskId,
          title: taskTitle.optional(),
          closed: z.boolean().optional().describe('True to close the task; false to reopen it.'),
        })
        .refine(({ title, closed }) => title !== undefined || closed !== undefined, {
          message: 'Supply title or closed to update a task.',
        }),
      annotations: {
        readOnlyHint: false,
        destructiveHint: true,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async ({ id, title, closed }) => {
      try {
        const changes = {
          ...(title !== undefined ? { title } : {}),
          ...(closed !== undefined ? { closed } : {}),
        }
        const { data } = await supabase
          .from('tasks')
          .update(changes)
          .eq('id', id)
          .select(taskFields)
          .maybeSingle()
          .throwOnError()

        return data ? jsonResult({ task: data }) : errorResult(taskNotFound)
      } catch (error) {
        return runtimeErrorResult(error)
      }
    }
  )

  server.registerTool(
    'delete_task',
    {
      description:
        'Permanently delete one of your tasks by ID. Use update_task with closed: true to keep a completed task instead.',
      inputSchema: z.strictObject({ id: taskId }),
      annotations: {
        readOnlyHint: false,
        destructiveHint: true,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async ({ id }) => {
      try {
        const { data } = await supabase
          .from('tasks')
          .delete()
          .eq('id', id)
          .select('id')
          .maybeSingle()
          .throwOnError()

        return data ? jsonResult({ deleted: true, id: data.id }) : errorResult(taskNotFound)
      } catch (error) {
        return runtimeErrorResult(error)
      }
    }
  )
}

/// <reference types="vite/types/importMeta.d.ts" />
import { createFileRoute } from '@tanstack/react-router'

import { ConnectedAgents } from '@/registry/default/blocks/headless-app-tanstack/components/connected-agents'

const PRODUCT_NAME = import.meta.env.VITE_PRODUCT_NAME?.trim() || 'Your product'
const MCP_SERVER_URL = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/mcp-server`

// Nested under _protected, so the layout route redirects signed-out visitors
// before this renders.
export const Route = createFileRoute('/_protected/agents')({
  component: AgentsPage,
})

function AgentsPage() {
  return (
    <main className="flex min-h-svh items-center justify-center p-6 md:p-10">
      <ConnectedAgents
        className="w-full max-w-lg"
        mcpServerUrl={MCP_SERVER_URL}
        productName={PRODUCT_NAME}
      />
    </main>
  )
}

import { Check, Copy } from 'lucide-react'
import { useEffect, useState } from 'react'

import { cn } from '@/lib/utils'
import {
  useOAuthGrants,
  type OAuthGrant,
} from '@/registry/default/blocks/headless-app-tanstack/hooks/use-oauth-grants'
import { Button } from '@/registry/default/components/ui/button'

const buildPrompt = (productName: string, mcpServerUrl: string) =>
  `Connect to ${productName} using this MCP server:\n\n${mcpServerUrl}\n\nUse your MCP connection setup to authorize access in my browser. Then call whoami to verify the connection and list the available tools.`

const formatDate = (value: string) =>
  new Date(value).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' })

function ConnectAgent({
  productName,
  mcpServerUrl,
}: {
  productName: string
  mcpServerUrl: string
}) {
  const [copied, setCopied] = useState<'url' | 'prompt' | null>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!copied) return
    const timeout = window.setTimeout(() => setCopied(null), 2000)
    return () => window.clearTimeout(timeout)
  }, [copied])

  const copy = async (type: 'url' | 'prompt') => {
    setError(null)
    try {
      await navigator.clipboard.writeText(
        type === 'url' ? mcpServerUrl : buildPrompt(productName, mcpServerUrl)
      )
      setCopied(type)
    } catch {
      setCopied(null)
      setError('Unable to copy. Select and copy the server URL above.')
    }
  }

  return (
    <section className="flex flex-col gap-3" aria-label="Connect an agent">
      <h2 className="font-medium">Connect an agent</h2>
      <p className="text-sm text-muted-foreground">
        Add this server URL in your agent’s MCP settings, then sign in and approve access.
      </p>
      <div className="overflow-hidden rounded-lg border bg-muted">
        <pre className="overflow-x-auto whitespace-pre-wrap break-all p-4 font-mono text-sm">
          {mcpServerUrl}
        </pre>
        <div className="flex flex-wrap justify-end gap-2 border-t p-2">
          <Button type="button" size="sm" variant="outline" onClick={() => void copy('prompt')}>
            {copied === 'prompt' ? 'Prompt copied' : 'Copy prompt'}
          </Button>
          <Button type="button" size="sm" variant="outline" onClick={() => void copy('url')}>
            {copied === 'url' ? <Check className="size-4" /> : <Copy className="size-4" />}
            {copied === 'url' ? 'URL copied' : 'Copy URL'}
          </Button>
        </div>
      </div>
      <p className="text-xs text-muted-foreground">
        Use the prompt if your agent supports adding MCP servers through chat.
      </p>
      {copied && (
        <span role="status" className="sr-only">
          Copied to clipboard
        </span>
      )}
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
    </section>
  )
}

function GrantRow({
  grant,
  isRevoking,
  disabled,
  onRevoke,
}: {
  grant: OAuthGrant
  isRevoking: boolean
  disabled: boolean
  onRevoke: () => void
}) {
  return (
    <li className="flex items-center gap-4 p-4">
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        <span className="truncate font-medium">{grant.client.name}</span>
        <span className="truncate text-muted-foreground">
          Authorized {formatDate(grant.granted_at)}
          {grant.scopes.length > 0 && ` · ${grant.scopes.join(', ')}`}
        </span>
      </div>
      <Button type="button" size="sm" variant="outline" disabled={disabled} onClick={onRevoke}>
        {isRevoking ? 'Revoking access...' : 'Revoke access'}
      </Button>
    </li>
  )
}

export interface ConnectedAgentsViewProps extends React.ComponentPropsWithoutRef<'div'> {
  mcpServerUrl: string
  productName?: string
  grants?: OAuthGrant[] | null
  isLoading?: boolean
  error?: string | null
  revokingClientId?: string | null
  onRefresh?: () => void
  onRevoke?: (clientId: string) => void
}

export function ConnectedAgentsView({
  mcpServerUrl,
  productName = 'this app',
  grants = null,
  isLoading = false,
  error = null,
  revokingClientId = null,
  onRefresh,
  onRevoke,
  className,
  ...props
}: ConnectedAgentsViewProps) {
  return (
    <div className={cn('flex flex-col gap-6', className)} {...props}>
      <div className="flex flex-col space-y-1.5">
        <h1 className="text-2xl font-semibold leading-none tracking-tight">Connected agents</h1>
        <p className="text-sm text-muted-foreground">
          Authorize agents to use {productName} on your behalf.
        </p>
      </div>

      <ConnectAgent productName={productName} mcpServerUrl={mcpServerUrl} />

      <section className="flex flex-col gap-3" aria-label="Authorized agents">
        <div className="flex items-center justify-between gap-4">
          <h2 className="font-medium">Authorized agents</h2>
          {onRefresh && (
            <Button
              type="button"
              size="sm"
              variant="outline"
              disabled={isLoading || revokingClientId !== null}
              onClick={onRefresh}
            >
              {isLoading ? 'Refreshing...' : 'Refresh'}
            </Button>
          )}
        </div>
        {isLoading && (
          <p role="status" className="text-sm text-muted-foreground">
            Loading connected agents...
          </p>
        )}
        {grants && grants.length > 0 && (
          <ul className="divide-y rounded-lg border bg-muted text-sm">
            {grants.map((grant) => (
              <GrantRow
                key={grant.client.id}
                grant={grant}
                isRevoking={revokingClientId === grant.client.id}
                disabled={isLoading || revokingClientId !== null || !onRevoke}
                onRevoke={() => onRevoke?.(grant.client.id)}
              />
            ))}
          </ul>
        )}
        {!isLoading && !error && grants?.length === 0 && (
          <p className="text-sm text-muted-foreground">
            No agents authorized yet. Connect an agent using the server URL above.
          </p>
        )}
        {error && (
          <p role="alert" className="text-sm text-destructive">
            {error}
          </p>
        )}
        {grants && grants.length > 0 && (
          <p className="text-xs text-muted-foreground">
            Revoking access prevents an agent from renewing its session. Its current access token
            may work until it expires.
          </p>
        )}
      </section>
    </div>
  )
}

interface ConnectedAgentsProps extends React.ComponentPropsWithoutRef<'div'> {
  mcpServerUrl: string
  productName?: string
}

export function ConnectedAgents(props: ConnectedAgentsProps) {
  const { grants, error, isLoading, revokingClientId, refresh, revoke } = useOAuthGrants()

  return (
    <ConnectedAgentsView
      grants={grants}
      error={error}
      isLoading={isLoading}
      revokingClientId={revokingClientId}
      onRefresh={() => void refresh()}
      onRevoke={(clientId) => void revoke(clientId)}
      {...props}
    />
  )
}

import type { OAuthGrant } from '@supabase/supabase-js'
import { useCallback, useEffect, useRef, useState } from 'react'

import { createClient } from '@/registry/default/clients/tanstack/lib/supabase/client'

// Revocation invalidates refresh tokens. Already-issued access tokens can still
// be accepted by the MCP server until they expire.
const useOAuthGrants = () => {
  const [grants, setGrants] = useState<OAuthGrant[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [revokingClientId, setRevokingClientId] = useState<string | null>(null)
  const mounted = useRef(false)
  const requestId = useRef(0)
  const isRevoking = useRef(false)

  const refresh = useCallback(async () => {
    if (!mounted.current || isRevoking.current) return
    const id = ++requestId.current
    setIsLoading(true)
    setError(null)

    try {
      const { data, error } = await createClient().auth.oauth.listGrants()
      if (error) throw error
      if (mounted.current && id === requestId.current) setGrants(data)
    } catch (error) {
      if (mounted.current && id === requestId.current) {
        setError(
          `Unable to load connected agents. ${error instanceof Error ? error.message : 'Try refreshing the list.'}`
        )
      }
    } finally {
      if (mounted.current && id === requestId.current) setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    mounted.current = true
    const onFocus = () => void refresh()
    void refresh()
    window.addEventListener('focus', onFocus)
    return () => {
      mounted.current = false
      window.removeEventListener('focus', onFocus)
    }
  }, [refresh])

  const revoke = useCallback(async (clientId: string) => {
    if (!mounted.current || isRevoking.current) return
    isRevoking.current = true
    // A list request started before revocation must not restore the removed grant.
    const id = ++requestId.current
    setIsLoading(false)
    setRevokingClientId(clientId)
    setError(null)

    try {
      const { error } = await createClient().auth.oauth.revokeGrant({ clientId })
      if (error) throw error
      if (mounted.current && id === requestId.current) {
        setGrants((current) => current?.filter((grant) => grant.client.id !== clientId) ?? null)
      }
    } catch (error) {
      if (mounted.current && id === requestId.current) {
        setError(
          `Unable to revoke access. ${error instanceof Error ? error.message : 'Try revoking access again.'}`
        )
      }
    } finally {
      isRevoking.current = false
      if (mounted.current && id === requestId.current) setRevokingClientId(null)
    }
  }, [])

  return { grants, error, isLoading, revokingClientId, refresh, revoke }
}

type UseOAuthGrantsReturn = ReturnType<typeof useOAuthGrants>

export { useOAuthGrants, type OAuthGrant, type UseOAuthGrantsReturn }

import 'jsr:@supabase/functions-js@2.108.2/edge-runtime.d.ts'

import { createMcpHandler, McpServer } from 'npm:@modelcontextprotocol/server@2.0.0'
import { pipeline } from 'npm:@supabase/middleware@0.5.0'
import {
  withOAuthProtectedResource,
  withSupabase,
  type SupabaseContext,
} from 'npm:@supabase/server@1.6.0'

import { registerTools, type ToolContext } from './tools/index.ts'

// An MCP server as a single Supabase Edge Function, composed as a pipeline:
//
//   withOAuthProtectedResource  OAuth discovery for external MCP clients. Runs
//                               before the auth gate so unauthenticated clients
//                               can fetch the RFC 9728 metadata, and adds the
//                               WWW-Authenticate challenge to the gate's 401.
//   withSupabase                Verifies the user access token and builds an
//                               RLS-scoped client, so both embedded product
//                               agents and external OAuth clients act as the
//                               signed-in user.
//   handleMcp                   MCP transport and tools (./tools/index.ts).
//
// On Supabase Edge Functions the public URLs in the OAuth metadata are derived
// automatically, locally and hosted. Off Edge Functions, pass `resourceServer`
// and `authorizationServer` to withOAuthProtectedResource.

function readTextEnv(name: string, fallback: string): string {
  return Deno.env.get(name)?.trim() || fallback
}

const SERVER_NAME = readTextEnv('MCP_SERVER_NAME', 'supabase-mcp')
const SERVER_DESCRIPTION = readTextEnv(
  'MCP_SERVER_DESCRIPTION',
  'MCP access to this Supabase project for the signed-in user.'
)

const SERVER_INSTRUCTIONS =
  `${SERVER_DESCRIPTION} ` +
  'Every tool runs as the signed-in Supabase user, so role grants and Row Level Security apply. ' +
  "Call tools/list to discover what this project exposes, and read a tool's description and " +
  'annotations before calling it — some tools have side effects.'

const CORS_HEADERS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
  'Access-Control-Allow-Headers':
    'Authorization, Content-Type, Accept, Mcp-Protocol-Version, Mcp-Session-Id, Mcp-Method, Mcp-Name',
  'Access-Control-Expose-Headers': 'WWW-Authenticate, Mcp-Session-Id',
}

function createServer(context: ToolContext): McpServer {
  const server = new McpServer(
    { name: SERVER_NAME, version: '1.0.0' },
    { instructions: SERVER_INSTRUCTIONS }
  )

  registerTools(server, context)
  return server
}

async function handleMcp(request: Request, ctx: SupabaseContext): Promise<Response> {
  // The server and its tools are bound to this caller for exactly one request.
  const handler = createMcpHandler(
    () =>
      createServer({
        supabase: ctx.supabase,
        // auth: 'user' guarantees both claim shapes before this handler runs.
        userClaims: ctx.userClaims!,
        jwtClaims: ctx.jwtClaims!,
      }),
    { onerror: (error) => console.error('MCP request failed', error) }
  )

  return handler.fetch(request)
}

// The handler is passed inline so TypeScript infers its context from the entries.
// Passing `handleMcp` directly collapses the inferred context to `object`.
Deno.serve(
  pipeline(
    [withOAuthProtectedResource(), withSupabase({ auth: 'user', cors: { headers: CORS_HEADERS } })],
    (request, ctx) => handleMcp(request, ctx)
  )
)

import type { SupabaseContext } from 'npm:@supabase/server@1.6.0'
import type { SupabaseClient } from 'npm:@supabase/supabase-js@2.108.2'

// Only expose the user-scoped client and verified identity to tools. Keeping
// supabaseAdmin out of this type makes bypassing RLS an explicit design choice.
export type ToolContext = {
  supabase: SupabaseClient
  userClaims: NonNullable<SupabaseContext['userClaims']>
  jwtClaims: NonNullable<SupabaseContext['jwtClaims']>
}

import type { CallToolResult } from 'npm:@modelcontextprotocol/server@2.0.0'

// Shared helpers for building MCP tool results, so every tool returns the same
// shape and signals failure the same way.

/**
 * A successful structured result with a JSON text fallback for older clients.
 */
export function jsonResult(value: unknown): CallToolResult {
  return {
    content: [{ type: 'text', text: JSON.stringify(value) ?? 'null' }],
    structuredContent: value ?? null,
  }
}

/**
 * A failed result. The message goes back to the model so it can correct itself,
 * so keep it actionable — and free of credentials, claims, and stack traces.
 */
export function errorResult(message: string): CallToolResult {
  return {
    isError: true,
    content: [{ type: 'text', text: message }],
  }
}

function readString(value: unknown, key: string): string | null {
  if (!value || typeof value !== 'object' || !(key in value)) return null
  const property = (value as Record<string, unknown>)[key]
  return typeof property === 'string' && property ? property : null
}

/**
 * Turn an unknown thrown value into a safe MCP error. Supabase API errors often
 * carry a `code` and `hint`, both of which help a model fix its next call.
 */
export function runtimeErrorResult(error: unknown): CallToolResult {
  const message = error instanceof Error ? error.message : String(error)
  const code = readString(error, 'code')
  const hint = readString(error, 'hint')

  return errorResult(
    [code ? `[${code}]` : null, message, hint ? `Hint: ${hint}` : null].filter(Boolean).join(' ')
  )
}

import type { McpServer } from 'npm:@modelcontextprotocol/server@2.0.0'

import { jsonResult } from './result.ts'
import type { ToolContext } from './types.ts'

// Answers from verified claims, demonstrating that every tool runs as the
// signed-in user. client_id is present for OAuth tokens and null for ordinary
// product sessions.
export function registerWhoamiTool(
  server: McpServer,
  { userClaims, jwtClaims }: ToolContext
): void {
  const clientId =
    typeof jwtClaims?.client_id === 'string' && jwtClaims.client_id ? jwtClaims.client_id : null

  server.registerTool(
    'whoami',
    {
      description: "Return the signed-in user's identity and OAuth client id, when present.",
      annotations: {
        readOnlyHint: true,
        destructiveHint: false,
        openWorldHint: false,
      },
    },
    () =>
      jsonResult({
        id: userClaims.id,
        email: userClaims.email ?? null,
        role: userClaims.role ?? null,
        client_id: clientId,
      })
  )
}

/// <reference types="vite/types/importMeta.d.ts" />
import { createBrowserClient } from '@supabase/ssr'

export function createClient() {
  return createBrowserClient(
    import.meta.env.VITE_SUPABASE_URL!,
    import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY!
  )
}

import { createServerClient } from '@supabase/ssr'
import { getCookies, setCookie } from '@tanstack/react-start/server'

export function createClient() {
  return createServerClient(
    process.env.VITE_SUPABASE_URL!,
    process.env.VITE_SUPABASE_PUBLISHABLE_KEY!,
    {
      cookies: {
        getAll() {
          return Object.entries(getCookies()).map(
            ([name, value]) =>
              ({
                name,
                value,
              }) as { name: string; value: string }
          )
        },
        setAll(cookies) {
          cookies.forEach((cookie) => {
            setCookie(cookie.name, cookie.value)
          })
        },
      },
    }
  )
}
